"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Plus, Trash2 } from "lucide-react";
import TaskFormModal from "./TaskFormModal";
import { deleteTask } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  const [isModalOpen, setIsModalOpen] = useState(false);

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="flex justify-between items-center mb-8 bg-white p-6 rounded-xl border shadow-sm">
        <h1 className="text-2xl font-bold">Project Documentatie</h1>
        <Button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white hover:bg-blue-700">
          <Plus className="w-4 h-4 mr-2" /> Nieuwe Taak
        </Button>
      </div>

      <div className="space-y-4">
        {initialTasks.map((task) => (
          <div key={task.id} className="p-5 bg-white border rounded-lg flex justify-between items-start shadow-sm">
            <div>
              <span className="text-xs font-bold text-blue-600 uppercase tracking-wider">{task.sprint}</span>
              <h3 className="text-xl font-semibold mt-1">{task.title}</h3>
              <p className="text-gray-500 mt-1">{task.description}</p>
            </div>
            <Button variant="ghost" onClick={() => deleteTask(task.id)} className="text-red-500 hover:bg-red-50">
              <Trash2 className="w-5 h-5" />
            </Button>
          </div>
        ))}
      </div>

      <TaskFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
}