"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(data: any) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false };

    await prisma.task.create({
      data: {
        title: data.titel,
        description: `Sprint ${data.sprint} - ${data.documentType}`,
        // Tüm özel template alanlarını JSON olarak 'content' içine atıyoruz
        content: JSON.stringify(data), 
        sprint: data.sprint,
        status: "TODO",
        userId: user.id,
        // Şemanda varsa bunları da ekle:
        docType: data.documentType, 
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error(error);
    return { success: false };
  }
}

export async function updateTaskContent(id: string, fullData: any) {
  try {
    await prisma.task.update({
      where: { id },
      data: {
        content: JSON.stringify(fullData),
      },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}