"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { createNewTask } from "@/app/actions/task-actions";

export default function TaskFormModal({ open, setOpen }: any) {
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    
    const data = {
      titel: formData.get("titel"),
      sprint: formData.get("sprint"),
      documentType: formData.get("type"),
      datum: new Date().toLocaleDateString("nl-NL"),
    };

    const res = await createNewTask(data);
    if (res.success) setOpen(false);
    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A] border-teal-400/30 text-white">
        <form onSubmit={handleSubmit} className="space-y-4">
          <DialogHeader>
            <DialogTitle className="text-teal-400 italic font-black">NIEUW DOCUMENT</DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div>
              <Label>Document Titel</Label>
              <Input name="titel" className="bg-[#070B24] border-teal-500/20" required />
            </div>
            <div>
              <Label>Sprint</Label>
              <Input name="sprint" type="number" defaultValue="1" className="bg-[#070B24] border-teal-500/20" />
            </div>
            <div>
              <Label>Type</Label>
              <select name="type" className="w-full p-2 bg-[#070B24] border border-teal-500/20 rounded text-teal-200">
                <option value="review">Sprint Review</option>
                <option value="retrospective">Retrospective</option>
                <option value="sprintplan">Sprint Plan</option>
                <option value="daily">Daily Scrum</option>
                <option value="release">Release Plan</option>
              </select>
            </div>
          </div>

          <DialogFooter>
            <Button type="submit" disabled={loading} className="bg-teal-400 text-black font-bold w-full">
              {loading ? "CREATING..." : "CREATE DOCUMENT"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}