"use client"

import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

const Dialog = DialogPrimitive.Root
const DialogTrigger = DialogPrimitive.Trigger
const DialogPortal = DialogPrimitive.Portal
const DialogClose = DialogPrimitive.Close

const DialogOverlay = ({ className, ...props }: any) => (
  <DialogPrimitive.Overlay className={cn("fixed inset-0 z-50 bg-black/50 backdrop-blur-sm", className)} {...props} />
)

const DialogContent = ({ className, children, ...props }: any) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Content className={cn("fixed left-[50%] top-[50%] z-50 w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-white p-6 shadow-lg sm:rounded-lg", className)} {...props}>
      {children}
      <DialogPrimitive.Close className="absolute right-4 top-4 opacity-70 hover:opacity-100"><X className="h-4 w-4" /></DialogPrimitive.Close>
    </DialogPrimitive.Content>
  </DialogPortal>
)

const DialogHeader = ({ className, ...props }: any) => (<div className={cn("flex flex-col space-y-1.5 text-left", className)} {...props} />)
const DialogFooter = ({ className, ...props }: any) => (<div className={cn("flex justify-end space-x-2 mt-4", className)} {...props} />)
const DialogTitle = ({ className, ...props }: any) => (<DialogPrimitive.Title className={cn("text-lg font-semibold", className)} {...props} />)
const DialogDescription = ({ className, ...props }: any) => (<DialogPrimitive.Description className={cn("text-sm text-gray-500", className)} {...props} />)

export { Dialog, DialogTrigger, DialogContent, DialogHeader, DialogFooter, DialogTitle, DialogDescription, DialogClose }